    if (userAgent.indexOf('Win') !== -1) {
        return 'Windows';
    } else if (userAgent.indexOf('Mac') !== -1) {
        return 'MacOS';
    } else if (/Android/.test(userAgent)) {
        return 'Android';
    } else if (userAgent.indexOf('Linux') !== -1) {
        return 'Linux';
    } else if (/iPhone|iPad|iPod/.test(userAgent)) {
        return 'iOS';
    } else {
        return 'Unknown';
    }
}
